turns.assistant:
{
  "objective": "Create a globally coherent operating model that preserves necessary regional variation while resolving escalation ambiguity, compliance divergence, and goal conflict.",
  "design_principle": "Standardize decision rights, risk thresholds, data definitions, and planning interfaces globally; localize legally required controls, market execution, and customer-specific exceptions.",
  "portfolio": [
    {
      "change": "Global decision-rights charter",
      "causal_mechanism": "Ambiguity about who decides creates delay, duplicated approvals, and inconsistent outcomes.",
      "operating_model_change": "Define decision owners, required consultees, escalation rights, and delegation limits for recurring decisions across global, regional, and country levels.",
      "success_measures": ["Decision cycle time", "Duplicate approvals", "Decisions reopened due to unclear ownership"]
    },
    {
      "change": "Tiered escalation architecture",
      "causal_mechanism": "Escalations are triggered by personality, hierarchy, or local custom rather than customer and business risk.",
      "operating_model_change": "Use common severity tiers based on customer impact, regulatory exposure, financial exposure, reputational risk, and time sensitivity. Attach mandatory response times and escalation paths to each tier.",
      "success_measures": ["Time to acknowledge", "Time to contain", "Missed escalation thresholds", "Unnecessary executive escalations"]
    },
    {
      "change": "Single global incident command model",
      "causal_mechanism": "Cross-border incidents fragment across functions and time zones, producing conflicting communications and ownership gaps.",
      "operating_model_change": "Create one incident commander role, regional response leads, a standard incident lifecycle, and a single source of truth for status, decisions, and customer communications.",
      "success_measures": ["Cross-region incidents with one accountable commander", "Time to coordinated response", "Conflicting external messages"]
    },
    {
      "change": "Global compliance control baseline with local addenda",
      "causal_mechanism": "Regional compliance differences are handled either by uncontrolled exceptions or by excessive global standardization.",
      "operating_model_change": "Establish non-negotiable global controls, a documented country-by-country addendum, an exception authority, and periodic legal review. Encode controls directly into workflows where possible.",
      "success_measures": ["Control adherence", "Audit findings", "Unapproved local variations", "Exception aging"]
    },
    {
      "change": "Compliance interpretation council",
      "causal_mechanism": "Different regions interpret the same requirement differently, causing inconsistent operating practices and repeated legal questions.",
      "operating_model_change": "Create a cross-functional council that issues binding interpretations, maintains a decision log, and publishes reusable guidance for comparable cases.",
      "success_measures": ["Interpretation turnaround time", "Repeated questions", "Regional variance for equivalent scenarios"]
    },
    {
      "change": "Common customer-risk taxonomy",
      "causal_mechanism": "Countries and functions use incompatible definitions of strategic, sensitive, at-risk, or regulated customers.",
      "operating_model_change": "Adopt shared definitions, scoring rules, evidence requirements, and review thresholds for customer risk and escalation priority.",
      "success_measures": ["Inter-rater consistency", "Risk reclassification rate", "High-risk cases identified before impact"]
    },
    {
      "change": "Quarterly goal architecture with shared outcomes",
      "causal_mechanism": "Competing quarterly goals optimize local or functional performance at the expense of enterprise outcomes.",
      "operating_model_change": "Set a small number of enterprise outcomes first, then cascade regional and functional goals with explicit contribution maps, trade-off rules, and capacity constraints.",
      "success_measures": ["Goal conflicts identified before quarter start", "Cross-functional dependency misses", "Enterprise outcomes achieved despite local target changes"]
    },
    {
      "change": "Portfolio-level prioritization forum",
      "causal_mechanism": "Conflicts persist because no body has authority to make explicit trade-offs across countries, customers, and functions.",
      "operating_model_change": "Use a recurring forum with a fixed decision mandate, comparable business cases, constrained capacity data, and documented trade-off decisions.",
      "success_measures": ["Time to resolve priority conflicts", "Work started without capacity", "Priority reversals"]
    },
    {
      "change": "Funding and capacity tied to strategic priorities",
      "causal_mechanism": "Declared priorities do not change resource allocation, so teams continue optimizing legacy commitments.",
      "operating_model_change": "Allocate budget, specialist capacity, and leadership attention through the same portfolio priorities used for quarterly planning; reserve explicit capacity for regulatory and incident work.",
      "success_measures": ["Resource alignment to priorities", "Unfunded priority work", "Regulatory work displacing planned work"]
    },
    {
      "change": "Global operating metrics and data contract",
      "causal_mechanism": "Leaders debate definitions and local reports instead of managing performance.",
      "operating_model_change": "Create common metric definitions, ownership, calculation rules, reporting cadence, data-quality standards, and permitted regional dimensions.",
      "success_measures": ["Metric reconciliation effort", "Data-quality defects", "Decisions made from common dashboards"]
    },
    {
      "change": "Integrated management cadence",
      "causal_mechanism": "Escalations, compliance, performance, and planning are reviewed in disconnected meetings with inconsistent facts.",
      "operating_model_change": "Link weekly operational reviews, monthly risk reviews, and quarterly portfolio reviews through shared inputs, decision logs, and carry-forward actions.",
      "success_measures": ["Open actions past due", "Repeated topics across forums", "Decisions completed within the intended cadence"]
    },
    {
      "change": "Cross-region operating councils",
      "causal_mechanism": "Country teams optimize locally and lack a mechanism to share patterns or resolve interface problems.",
      "operating_model_change": "Create councils for customer operations, compliance, risk, and enabling functions with rotating regional representation and explicit decision rights.",
      "success_measures": ["Reusable practices adopted", "Cross-region issue resolution", "Local workarounds retired"]
    },
    {
      "change": "Incentive and performance-management alignment",
      "causal_mechanism": "People follow measured and rewarded behavior, even when it conflicts with enterprise goals or safe escalation.",
      "operating_model_change": "Balance country and functional targets with enterprise outcomes, collaboration measures, control adherence, and timely escalation behavior. Avoid incentives based solely on local revenue, cost, or closure volume.",
      "success_measures": ["Cross-boundary objective achievement", "Late or suppressed escalations", "Control breaches linked to target pressure"]
    },
    {
      "change": "Escalation and compliance capability program",
      "causal_mechanism": "Rules fail when employees cannot recognize thresholds, navigate regional differences, or communicate under pressure.",
      "operating_model_change": "Train role-specific scenarios, certify incident and compliance roles, run simulations, and provide decision aids embedded in normal workflows.",
      "success_measures": ["Certification coverage", "Simulation performance", "Correct first-time routing", "Training-to-incident error rate"]
    },
    {
      "change": "Post-incident and post-quarter learning loop",
      "causal_mechanism": "The organization repeatedly experiences the same failures because learning is informal and changes are not tracked to closure.",
      "operating_model_change": "Require blameless reviews for material escalations, compliance events, and major goal conflicts; assign owners, deadlines, and verification tests for corrective actions.",
      "success_measures": ["Repeat-event rate", "Corrective actions closed and verified", "Time from learning to control or process change"]
    }
  ],
  "global_guardrails": [
    "No country-level variation without a documented legal, customer, market, or operational rationale.",
    "No global standard that conflicts with mandatory local law; local exceptions require evidence and an accountable owner.",
    "Every escalation threshold must have an owner, response time, communication rule, and closure definition.",
    "Every quarterly goal must identify dependencies, required capacity, and the enterprise outcome it supports.",
    "Every major operating-model decision must be recorded with rationale, scope, effective date, and review date."
  ],
  "recommended_sequence": {
    "phase_1_0_to_30_days": [
      "Map current decision rights, escalation paths, compliance variations, metrics, and quarterly conflicts.",
      "Name accountable executives for the operating model.",
      "Freeze creation of new local escalation rules unless legally required."
    ],
    "phase_2_31_to_90_days": [
      "Launch the decision-rights charter, escalation tiers, global compliance baseline, risk taxonomy, and common metric definitions.",
      "Pilot the model in two materially different regions.",
      "Run one cross-region incident simulation and one quarterly prioritization cycle."
    ],
    "phase_3_91_to_180_days": [
      "Scale the validated model across all countries.",
      "Align funding, incentives, management cadence, and workflow tooling.",
      "Retire duplicative councils, reports, and local procedures."
    ],
    "phase_4_ongoing": [
      "Review thresholds, local addenda, metrics, and incentives quarterly.",
      "Use incident and goal-conflict data to refine the operating model rather than adding ad hoc rules."
    ]
  },
  "primary_outcome": "A federated operating model: globally consistent on decision rights, risk, controls, data, and trade-off mechanisms; locally adaptable on legally required controls and market execution."
}
